def f(g):
    H,W=len(g),len(g[0])
    # find cross: a full row and a full column of same color L (not background)
    from collections import Counter
    cnt=Counter(x for r in g for x in r)
    bg=cnt.most_common(1)[0][0]
    L=None
    for v in cnt:
        if v!=bg:
            if any(all(r[j]==v for j in range(W)) for r in g) and any(all(g[i][j]==v for i in range(H)) for j in range(W)):
                L=v
    rind=[i for i in range(H) if all(g[i][j]==L for j in range(W))][0]
    cind=[j for j in range(W) if all(g[i][j]==L for i in range(H))][0]
    # noise pixels: not bg, not L
    pts=[(i,j,g[i][j]) for i in range(H) for j in range(W) if g[i][j] not in (bg,L)]
    out=[[bg]*W for _ in range(H)]
    for i,j,_ in pts:
        ii=i if i<rind else i-1; jj=j if j<cind else j-1
        for a,b in [(ii,jj),(ii,W-1-jj),(H-1-ii,jj),(H-1-ii,W-1-jj)]:
            out[a][b]=L
    return out
